import type { ReactNode } from "react";
type Tone = "neutral" | "success" | "warning" | "danger";
type BadgeProps = { tone?: Tone; size?: "sm" | "md"; children: ReactNode };
export function Badge({ tone = "neutral", size = "md", children }: BadgeProps) { return <span className={`badge badge--${tone} badge--${size}`}>{children}</span>; }
type Status = "OPEN" | "IN_PROGRESS" | "CLOSED";
const STATUS_VIEW: Record<Status, { tone: Tone; label: string }> = { OPEN: { tone: "success", label: "Otwarty" }, IN_PROGRESS: { tone: "warning", label: "W toku" }, CLOSED: { tone: "neutral", label: "Zamknięty" } };
export function StatusBadge({ status }: { status: Status }) { const view = STATUS_VIEW[status]; return <Badge tone={view.tone}>{view.label}</Badge>; }
type Ticket = { id: number; title: string; status: Status; assignee: string | null };
function Row({ ticket }: { ticket: Ticket }) { return <tr><td>{ticket.id}</td><td>{ticket.title}</td><td><StatusBadge status={ticket.status}/></td><td>{ticket.assignee ?? "—"}</td></tr>; }
export function TicketTable({ tickets }: { tickets: readonly Ticket[] }) { return <table className="ticket-table"><thead><tr><th scope="col">ID</th><th scope="col">Tytuł</th><th scope="col">Status</th><th scope="col">Osoba</th></tr></thead><tbody>{tickets.length === 0 ? <tr><td colSpan={4}>Brak ticketów do wyświetlenia</td></tr> : tickets.map(t => <Row key={t.id} ticket={t}/>)}</tbody></table>; }

